function prime_fib(n) {
    function isPrime(num) {
        if (num <= 1) return false;
        if (num <= 3) return true;
        if (num % 2 === 0 || num % 3 === 0) return false;
        for (let i = 5; i * i <= num; i += 6) {
            if (num % i === 0 || num % (i + 2) === 0) return false;
        }
        return true;
    }

    function fib(num) {
        if (num <= 1) return num;
        let a = 0, b = 1, c;
        for (let i = 2; i <= num; i++) {
            c = a + b;
            a = b;
            b = c;
        }
        return b;
    }

    let count = 0;
    let i = 1;
    while (true) {
        let fibNum = fib(i);
        if (isPrime(fibNum)) {
            count++;
            if (count === n) return fibNum;
        }
        i++;
