function pancake_sort(nums) {
    function flip(subArray, k) {
        let start = 0;
        let end = k;
        while (start < end) {
            let temp = subArray[start];
            subArray[start] = subArray[end];
            subArray[end] = temp;
            start++;
            end--;
        }
    }

    let n = nums.length;
    for (let size = n; size > 1; size--) {
        let maxIndex = 0;
        for (let i = 1; i < size; i++) {
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
        }

        if (maxIndex !== size - 1) {
            flip(nums, maxIndex);
            flip(nums, size - 1);
        }
    }
    return nums;
}

