function get_total_number_of_sequences(m, n) {
    if (n === 0) return 1;
    if (m === 0) return 0;

    let dp = Array.from({ length: n + 1 }, () => Array(m + 1).fill(0));

    for (let i = 1; i <= m; i++) {
        dp[1][i] = 1;
    }

    for (let length = 2; length <= n; length++) {
        for (let maxVal = 1; maxVal <= m; maxVal++) {
            dp[length][maxVal] = dp[length][maxVal - 1];
            if (2 * (maxVal - 1) < maxVal) {
                dp[length][maxVal] += dp[length - 1][maxVal - 1];
            }
        }
    }

    return dp[n][m];
}

