    const n = Y.length;
    const o = Z.length;

    const L = Array.from({ length: m + 1 }, () => Array.from({ length: n + 1 }, () => Array(o + 1).fill(0)));

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            for (let k = 1; k <= o; k++) {
                if (X[i - 1] === Y[j - 1] && Y[j - 1] === Z[k - 1]) {
                    L[i][j][k] = L[i - 1][j - 1][k - 1] + 1;
                } else {
                    L[i][j][k] = Math.max(
                        Math.max(L[i - 1][j][k], L[i][j - 1][k]),
                        L[i][j][k - 1]
