    /* Since there are two arrays of size n, we
    consider first two elements of both arrays for
    comparison */
    for (count = 0; count <= n; count++){
        /* Below is to handle end cases */
        if (i == n){
            m1 = m2;
            m2 = arr2[0];
            break;
        }
        else if (j == n){
            m1 = m2;
