function findFirstOccurrence(arr, x, n) {
    let low = 0, high = n - 1;
    while (low <= high) {
        let mid = Math.floor((low + high) / 2);
        if ((mid == 0 || x > arr[mid - 1]) && (arr[mid] == x)) return mid;
